{
  "name": "通用TCP探测器/数据采集设备",
  "name_en": "Generic TCP Detector / Data Acquisition Instrument",
  "manufacturer": "",
  "description": "这是一类通过 TCP/IP 与上位机通信的通用实验探测器或数据采集设备，可输出标量、一维曲线或二维图像数据。它适合把远程传感器、线阵/面阵探测器、相机或其他测量前端接入实验自动化系统，用于实时采集、传输和显示测量结果。",
  "description_en": "This is a generic laboratory detector or data acquisition instrument that communicates with a host computer over TCP/IP and can provide scalar, 1D trace, or 2D image data. It is suitable for integrating remote sensors, line or area detectors, cameras, or other measurement front ends into an automated lab system for real-time acquisition, transfer, and display of measurement data.",
  "tag_hints": [
    "TCP/IP instrument control",
    "remote data acquisition",
    "detector readout",
    "2D imaging",
    "1D trace acquisition",
    "laboratory automation"
  ],
  "actions": [
    {
      "action_name": "auto-command_to_from_client",
      "description": "处理来自客户端的控制命令",
      "description_en": "Process an incoming control command from the client"
    },
    {
      "action_name": "auto-send_data",
      "description": "向客户端发送采集数据",
      "description_en": "Send acquired data to the client"
    },
    {
      "action_name": "auto-read_data",
      "description": "从网络连接读取数据",
      "description_en": "Read data from the network connection"
    },
    {
      "action_name": "auto-data_ready",
      "description": "发送数据已就绪通知",
      "description_en": "Notify that acquired data are ready"
    },
    {
      "action_name": "auto-command_done",
      "description": "标记当前命令已完成",
      "description_en": "Mark the current command as completed"
    },
    {
      "action_name": "auto-commit_settings",
      "description": "设置采集参数值",
      "description_en": "Set an acquisition parameter value"
    },
    {
      "action_name": "auto-ini_detector",
      "description": "初始化探测器或采集设备",
      "description_en": "Initialize the detector or acquisition device"
    },
    {
      "action_name": "auto-close",
      "description": "关闭并反初始化设备",
      "description_en": "Close and uninitialize the device"
    },
    {
      "action_name": "auto-grab_data",
      "description": "开始采集数据",
      "description_en": "Start data acquisition"
    },
    {
      "action_name": "auto-stop",
      "description": "停止采集",
      "description_en": "Stop acquisition"
    },
    {
      "action_name": "auto-set_0D_Mock_data",
      "description": "生成测试用零维模拟数据",
      "description_en": "Generate mock 0D data for testing"
    },
    {
      "action_name": "auto-set_1D_Mock_data",
      "description": "生成测试用一维模拟数据",
      "description_en": "Generate mock 1D data for testing"
    },
    {
      "action_name": "auto-set_2D_Mock_data",
      "description": "生成测试用二维模拟数据",
      "description_en": "Generate mock 2D data for testing"
    }
  ]
}

